const tour=(function(){
  let active=false,step=0,steps=[],els={};
  function pos(el){const r=el.getBoundingClientRect();return{top:r.top,left:r.left,width:r.width,height:r.height}}
  function createDOM(){
    const d=document.createElement('div');d.id='tour-layer';
    d.innerHTML='<div class="tour-backdrop"></div><div class="tour-spot"></div><div class="tour-tooltip"><div class="tour-arrow"></div><div class="tour-header"><span class="tour-counter"></span><button class="tour-close" aria-label="Fermer">&times;</button></div><div class="tour-progress"><div class="tour-progress-fill"></div></div><h3 class="tour-title"></h3><p class="tour-text"></p><div class="tour-nav"><button class="tour-btn tour-prev">\u2190 Pr\u00e9c\u00e9dent</button><button class="tour-btn tour-skip">Passer le guide</button><button class="tour-btn tour-btn-primary tour-next">Suivant \u2192</button></div></div>';
    document.body.appendChild(d);
    els={layer:d,backdrop:d.querySelector('.tour-backdrop'),spot:d.querySelector('.tour-spot'),tip:d.querySelector('.tour-tooltip'),arrow:d.querySelector('.tour-arrow'),counter:d.querySelector('.tour-counter'),progress:d.querySelector('.tour-progress-fill'),title:d.querySelector('.tour-title'),text:d.querySelector('.tour-text'),prev:d.querySelector('.tour-prev'),next:d.querySelector('.tour-next'),skip:d.querySelector('.tour-skip'),close:d.querySelector('.tour-close')};
    els.next.addEventListener('click',()=>go(1));els.prev.addEventListener('click',()=>go(-1));
    els.skip.addEventListener('click',finish);els.close.addEventListener('click',finish);
    els.backdrop.addEventListener('click',finish);
  }
  function show(){
    if(!els.layer)createDOM();
    els.layer.classList.add('tour-active');
    const s=steps[step],n=steps.length;
    els.counter.textContent=(step+1)+' / '+n;
    els.progress.style.width=((step+1)/n*100)+'%';
    els.title.textContent=s.title;els.text.textContent=s.text;
    els.prev.style.display=step>0?'':'none';
    els.next.textContent=step<n-1?'Suivant \u2192':'Terminer';
    els.next.classList.toggle('tour-btn-finish',step===n-1);
    if(s.page&&state.page!==s.page){navigate(s.page);requestAnimationFrame(()=>requestAnimationFrame(()=>highlight(s)))}
    else highlight(s);
  }
  function highlight(s){
    const selectors=s.target?s.target.split(','):[];
    let el=null;for(const sel of selectors){el=document.querySelector(sel.trim());if(el)break}
    if(el){
      el.scrollIntoView({block:'center'});
      const p=pos(el);const pad=8;
      els.spot.style.cssText='display:block;top:'+(p.top-pad)+'px;left:'+(p.left-pad)+'px;width:'+(p.width+pad*2)+'px;height:'+(p.height+pad*2)+'px;border-radius:10px';
      const vp=el.getBoundingClientRect();
      const tipW=Math.min(340,window.innerWidth-32);
      let tTop,tLeft,arrowSide;
      if(vp.bottom+16+200<window.innerHeight){tTop=vp.bottom+16;arrowSide='top'}
      else if(vp.top-16-200>0){tTop=vp.top-16-200;arrowSide='bottom'}
      else{tTop=Math.max(20,vp.top);arrowSide='top'}
      tLeft=Math.max(16,Math.min(window.innerWidth-tipW-16,vp.left+vp.width/2-tipW/2));
      els.tip.style.cssText='top:'+tTop+'px;left:'+tLeft+'px;max-width:'+tipW+'px';
      els.arrow.className='tour-arrow tour-arrow-'+arrowSide;
      const arrowX=Math.max(24,Math.min(tipW-24,vp.left+vp.width/2-tLeft));
      els.arrow.style.left=arrowX+'px';
    }else{
      els.spot.style.display='none';
      els.tip.style.cssText='top:50%;left:50%;transform:translate(-50%,-50%);max-width:380px';
      els.arrow.className='tour-arrow';els.arrow.style.left='';
    }
  }
  function go(dir){
    if(!active)return;
    const ns=step+dir;
    if(ns<0)return;
    if(ns>=steps.length){finish();return}
    step=ns;show();
  }
  function finish(){
    active=false;step=0;
    if(els.layer)els.layer.classList.remove('tour-active');
    if(!guideDone)api('guide-done',{}).catch(()=>{});guideDone=true;
    render();
  }
  return{
    start(){if(active)return;active=true;step=0;steps=user()?.role==='admin'?tourAdminSteps:tourCoachSteps;show()},
    get active(){return active}
  };
})();
(function initSwipe(){let sx=0,sy=0,swiping=false;document.addEventListener('touchstart',e=>{const z=e.target.closest('[data-swipe="day"]');if(!z)return;sx=e.touches[0].clientX;sy=e.touches[0].clientY;swiping=true},{passive:true});document.addEventListener('touchend',e=>{if(!swiping)return;swiping=false;const dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)<40||Math.abs(dy)>Math.abs(dx))return;if(dx<0&&state.mobileDay<6){state.mobileDay++;render()}else if(dx>0&&state.mobileDay>0){state.mobileDay--;render()}},{passive:true})})();
(function initDragSelect(){let dragging=false,toggled=new Set();document.addEventListener('touchstart',e=>{const card=e.target.closest('.agenda-lesson:not(:disabled)');if(!card||card.dataset.action!=='toggle-course')return;dragging=true;toggled.clear()},{passive:true});document.addEventListener('touchmove',e=>{if(!dragging)return;const touch=e.touches[0],el=document.elementFromPoint(touch.clientX,touch.clientY)?.closest('.agenda-lesson:not(:disabled)');if(!el||el.dataset.action!=='toggle-course'||toggled.has(el.dataset.id))return;toggled.add(el.dataset.id);el.classList.toggle('drag-highlight')},{passive:true});document.addEventListener('touchend',async e=>{if(!dragging)return;dragging=false;if(toggled.size<2)return;const ids=[...toggled];toggled.clear();for(const id of ids){try{BC.toggle(db,id,user().id,state.period,current)}catch{}}render();for(const id of ids){try{await mutate('toggle',{id})}catch{}}render()},{passive:true})})();
document.addEventListener('click',async e=>{const button=e.target.closest('[data-go],[data-action]');if(!button||button.disabled||busy)return;try{if(button.dataset.go){if(button instanceof HTMLAnchorElement&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey))return;e.preventDefault();navigate(button.dataset.go);return}const action=button.dataset.action,id=button.dataset.id;
  const writes=['logout','add-club','remove-basket','finalize','export-csv','export-excel','print'];if(writes.includes(action)){busy=true;button.disabled=true;button.setAttribute('aria-busy','true')}
  if(action==='open-navigation')setNavigation(true);
  else if(action==='close-navigation')setNavigation(false);
  else if(action==='skip-content'){e.preventDefault();setNavigation(false,false);focusContent()}
  else if(action==='auth-role'){const role=button.dataset.role;state.authRole=role==='admin'||role==='coach'?role:(state.authRole==='coach'?'admin':'coach');state.authView='login';render()}
  else if(action==='auth-register'){state.authView='register';state.authRole='coach';render()}
  else if(action==='auth-login'){state.authView='login';render()}
  else if(action==='toggle-password'){const input=document.getElementById(button.dataset.target);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',show?'true':'false');button.textContent=show?'Masquer':'Afficher'}
  else if(action==='start-tour'){tour.start()}
  else if(action==='mobile-day'){state.mobileDay=Number(id)||0;render()}
  else if(action==='retry-bootstrap'){await bootstrap()}
  else if(action==='help-password'){state.authEmail=document.getElementById('email')?.value||state.authEmail||'';state.authView='forgot';render()}
  else if(action==='logout'){await api('logout',{});state.userId=null;db={...BC.createDB(),users:[]};state.dialog=null;state.navOpen=false;state.authView='login';state.authRole='coach';state.authEmail='';state.registrationNotice='';history.replaceState(null,'',location.pathname);await bootstrap()}
  else if(action==='target'){state.target=id;state.week=0;navigate('declare')}
  else if(action==='week-prev'||action==='week-next'){state.week=Math.max(0,Math.min(BC.weeks(state.period).length-1,state.week+(action==='week-next'?1:-1)));render()}
  else if(action==='toggle-course'){try{BC.toggle(db,id,user().id,state.period,current)}catch(e){toast(e.message,true);return}button.classList.toggle('selected');button.setAttribute('aria-pressed',String(button.classList.contains('selected')));const _sel=BC.selected(db,user().id,state.period);const _cEl=document.querySelector('.summary-total strong');if(_cEl)_cEl.textContent=_sel.length;const _cLbl=document.querySelector('.summary-total .muted');if(_cLbl)_cLbl.textContent=_sel.length===1?'cours sélectionné':'cours sélectionnés';mutate('toggle',{id}).then(()=>render()).catch(e=>{toast(e.message,true);render()})}
  else if(action==='add-club'){const count=await mutate('addClub',{target:state.target});navigate('basket');toast(count+(count===1?' cours ajouté au panier et réservé pour votre compte.':' cours ajoutés au panier et réservés pour votre compte.'))}
  else if(action==='remove-basket'){await mutate('removeBasket',{id});render();toast('Cours retiré du panier et remis à disposition.')}
  else if(action==='confirm-validation'){state.dialog={type:'validation'};render()}
  else if(action==='finalize'){const d=await mutate('validate');navigate('summary',d.id);toast('Déclaration enregistrée. Les cours sont verrouillés.')}
  else if(action==='summary'){navigate('summary',id)}
  else if(action==='close-dialog'){state.dialog=null;render()}
  else if(action==='new-course'||action==='edit-course'){requireAdmin();state.dialog={type:'course',id:action==='edit-course'?id:null};render()}
  else if(action==='delete-course'){requireAdmin();state.dialog={type:'delete',id};render()}
  else if(action==='password-dialog'){state.dialog={type:'password'};render()}
  else if(action==='email-preview'){state.dialog={type:'email',id};render()}
  else if(action==='coach-detail'){requireAdmin();state.dialog={type:'coach',id};render()}
  else if(action==='account-status'){requireAdmin();const coach=db.users.find(u=>u.id===id);state.dialog={type:'account',id,active:!coach.active};render()}
  else if(action==='delete-account'){requireAdmin();state.dialog={type:'deleteAccount',id};render()}
  else if(action==='retry-mail'){requireAdmin();state.dialog={type:'retryMail',id};render()}
  else if(action==='summary-csv'){const d=db.declarations.find(d=>d.id===id);if(!d||user().role!=='admin'&&d.coachId!==user().id)throw Error('Récapitulatif inaccessible.');download(csv(exportRows(d.items,d.coachId)),'boxing-center-'+d.period+'.csv','text/csv;charset=utf-8');toast('Récapitulatif CSV téléchargé.')}
  else if(action==='export-csv'||action==='export-excel'){requireAdmin();await api('state');const list=exportCourses();if(!list.length)throw Error('Aucune donnée à exporter.');download(action==='export-csv'?csv(exportRows(list)):BCExport.xlsx(exportRows(list)),'boxing-center-'+state.period+(action==='export-csv'?'.csv':'.xlsx'),action==='export-csv'?'text/csv;charset=utf-8':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');await mutate('logExport',{format:action==='export-csv'?'CSV':'Excel XLSX',target:state.exportTarget});render();toast('Export téléchargé.')}
  else if(action==='export-print'){requireAdmin();navigate('exportSummary')}
  else if(action==='print'){if(user().role==='admin')await mutate('logExport',{format:'Impression / PDF',target:state.exportTarget});window.print()}
}catch(error){toast(error.message,true)}finally{busy=false;if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy')}}});
document.addEventListener('change',e=>{const name=e.target.dataset.filter;if(!name)return;const value=e.target.value;if(name==='coachColor'){mutate('setCoachColor',{coachId:e.target.dataset.coachId,color:value}).then(()=>render()).catch(er=>toast(er.message,true));return}if(name==='exportPeriod'&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(value)){e.target.value=state.period;toast('Choisissez une période valide.',true);return}if(name==='month')state.period=state.period.slice(0,5)+BC.pad(value);else if(name==='year')state.period=value+state.period.slice(4);else if(name==='club')state.target=BC.targets.find(t=>t.club===value).id;else if(name==='target')state.target=value;else if(name==='exportPeriod')state.period=value;else state[name]=value;state.week=0;render()});
document.addEventListener('keydown',e=>{
  if(state.navOpen&&compactNavigation.matches){
    if(e.key==='Escape'){e.preventDefault();setNavigation(false);return}
    if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll('#app-navigation a[href],#app-navigation button:not(:disabled)')).filter(el=>el.getClientRects().length&&el.tabIndex!==-1),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
    return;
  }
  if(!state.dialog)return;if(e.key==='Escape'){state.dialog=null;render()}if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll('.modal-box button:not(:disabled),.modal-box input,.modal-box select,.modal-box a[href]'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
});
compactNavigation.addEventListener('change',()=>{const inSidebar=document.activeElement?.closest('#app-navigation');setNavigation(false,false);if(inSidebar){const next=compactNavigation.matches?document.querySelector('#navigation-toggle'):document.querySelector('.app-nav-link.active');next?.focus({preventScroll:true})}});
function routeId(id){try{return decodeURIComponent(id||'')}catch{return ''}}
window.addEventListener('popstate',()=>{const [page,id]=location.hash.slice(1).split('/');state.page=page||'dashboard';state.detailId=routeId(id);state.dialog=null;state.navOpen=false;render();focusContent()});
if(location.hash){const [page,id]=location.hash.slice(1).split('/');if(page==='reset'){state.authView='reset';state.resetToken=id;history.replaceState(null,'',location.pathname)}else{state.page=page;state.detailId=routeId(id)}}
bootstrap();
